// from src/locales/ja/blog.ts. Body + FAQs for article 'image-metadata-viewer-guide' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>写真には、目に見えない情報が隠れています。カメラの設定、撮影日時、使った機種、そして場合によっては撮影場所まで。ファイルの中に静かに記録されているのです。</p>\n<p>画像メタデータ確認ツールは、その隠れた情報を読み取り、分かりやすい形で表示してくれます。難解なバイナリデータを、誰でも読めるレポートに変えてくれるのです。</p>\n<p>この記事では、画像のメタデータとは何か、ツールで何が分かるのか、そして写真を共有する前にどう確認すればいいのかを解説します。プライバシーのリスク、JSONでの保存方法、削除済みファイルの確認方法も取り上げます。</p>\n<p><a href=\"/ja/gazou-metadeta-kakunin/\">画像メタデータ確認ツール</a>は、ブラウザの中だけで動作します。写真が自分の端末から外に出ることはありません。プライバシーのためのツールですから、これが何より大切なポイントです。</p>\n<h2 id=\"what-is-image-metadata\">画像のメタデータとは</h2>\n<p>画像のメタデータとは、画素そのものとは別に、画像ファイルの中に保存されているデータのことです。写真そのものではなく、写真についての情報を記録した、いわば裏面のラベルのようなものです。</p>\n<p>最も一般的なのがEXIF（エグジフ）です。正式にはExchangeable Image File Formatといい、カメラやスマホがシャッターを切るたびに自動で書き込みます。</p>\n<p>EXIFには、カメラのメーカーや機種、レンズの情報、絞り、シャッタースピード、ISO感度、焦点距離、フラッシュの状態、撮影した正確な日時などが含まれます。</p>\n<p>ほかのメタデータは別の場所に保存されています。PNGファイルには、作成者やソフト名、作成時刻などを記録するテキストチャンクがあります。WebPファイルにはEXIFブロックやアニメーション情報が入ることもあります。JPEGファイルにも、XMPパケットやコメントが含まれることがあります。</p>\n<p>こうした情報は、写真を眺めているだけでは決して見えません。確認するには専用のツールが必要です。ほとんどの人は一度も調べたことがありません。そのため、ネットに公開された写真は、持ち主が気づかないうちに多くの情報を漏らしているのです。</p>\n<h2 id=\"what-the-viewer-shows\">ツールで確認できる情報</h2>\n<p>画像をツールにドラッグすると、ファイルの生データを端末上で解析します。すぐに概要とプライバシーリスクの表示、そして見つかった項目をグループ分けした一覧が表示されます。</p>\n<p>概要には、ファイル形式、画素数（ピクセルサイズ）、ファイルサイズが表示されます。さらに、注意が必要な種類のメタデータが含まれているかどうかも分かります。</p>\n<p>一覧は見やすくグループ分けされています。カメラ関連の項目、露出関連のEXIF項目、GPS関連の項目、PNGやWebPのチャンクが、それぞれまとまって表示されます。</p>\n<p>注意が必要な項目には、琥珀色の「Privacy Tag」ラベルが付きます。代表的な例は、GPS座標、正確な撮影日時、撮影者名、カメラのシリアル番号、機種名などです。</p>\n<p>GPSデータがある場合は、警告ボックスにデコードされた緯度と経度が正確に表示されます。ワンクリックで<a href=\"/ja/gazou-metadeta-sakujo/\">画像メタデータ削除ツール</a>に移動できるので、すぐにファイルをきれいにできます。</p>\n<h2 id=\"exif-fields-explained\">EXIFの項目を解説</h2>\n<p>EXIFは、IFDと呼ばれるディレクトリに整理されています。ツールはJPEGファイルからTIFF IFD0、ExifIFD、GPSIFDの各テーブルを読み取るほか、PNGのeXIfブロックやWebPのEXIFチャンクも解析します。</p>\n<p>IFD0には、画像と端末に関する基本情報が入っています。カメラのメーカーや機種はここにあり、最後にファイルを編集したソフト名や著作権表示もここに記録されます。</p>\n<p>ExifIFDには、撮影時の露出情報が記録されています。シャッタースピード、絞り、ISO感度、焦点距離、測光モード、フラッシュの状態などが、このディレクトリに含まれます。</p>\n<p>GPSIFDには、位置情報が有理数（分数）で記録されています。ツールは度・分・秒を自動で10進数の緯度・経度に変換するので、座標をそのまま読むことができます。</p>\n<p>すべての項目がすべての写真にあるわけではありません。スクリーンショットにはカメラ情報がありませんし、メッセージアプリ経由で受け取った写真は、送信時にメタデータが削除されているためEXIFが残っていないことがほとんどです。</p>\n<p>項目が見つからないこと自体も、有益な情報です。そのファイルがすでに加工されているか、もともとカメラのオリジナルではなかったことを教えてくれるからです。</p>\n<h2 id=\"gps-and-privacy\">GPS情報とプライバシー</h2>\n<p>GPS座標は、写真に含まれる情報の中で最も注意が必要です。たった2つの数字だけで、自宅や職場、子どもの学校、写真を撮った正確な場所まで特定できてしまいます。</p>\n<p>ほとんどのカメラアプリでは、スマホがGPS情報を初期設定で記録します。座標は写真に何の痕跡も残さず静かに保存されるため、持ち主は存在に気づきません。</p>\n<p>削除されていない写真をネットで共有すると、ダウンロードした誰もがメタデータ確認ツールで位置情報を読み取れます。フリマアプリや掲示板、SNSの利用者も例外ではありません。</p>\n<p>ツールはこのリスクを目に見える形にします。GPSIFDタグがある場合、項目一覧のすぐ上に「GPS Location Coordinates Detected」という琥珀色のバナーが表示され、デコードされた座標が示されます。</p>\n<p>投稿前の確認は数秒で終わります。座標が表示されたら、公開する前に<a href=\"/ja/gazou-metadeta-sakujo/\">画像メタデータ削除ツール</a>で削除しましょう。</p>\n<h2 id=\"png-and-webp-chunks\">PNG・WebPの技術情報</h2>\n<p>JPEGばかりが注目されがちですが、PNGやWebPにも独自のメタデータがあります。ツールはこうした技術的なチャンクも読み取るので、隠れた情報は見逃しません。</p>\n<p>PNGファイルでは、ビット深度やカラータイプを記録するIHDRチャンクを読み取ります。印刷や表示の解像度を記録するpHYsチャンクも確認できます。</p>\n<p>PNGのテキストチャンクもプライバシーの観点で重要です。tEXtやiTXtチャンクにはソフト名、作成者名、コメント、作成時刻などが入ることがあります。tIMEチャンクにはファイルの最終更新時刻が記録されます。</p>\n<p>WebPファイルでは、アルファチャンネルやアニメーションの有無を示すVP8Xフラグを読み取ります。WebPのEXIFチャンクも同時にデコードされるので、WebPに含まれるカメラ情報も見逃しません。</p>\n<p>さらにツールは、ファイル名ではなくバイナリの「マジックバイト」から本当のファイル形式を判定します。PNGファイルを.jpgという名前に変えても、PNGとして正しく表示されます。</p>\n<h2 id=\"how-to-use-the-viewer\">使い方：5つのステップ</h2>\n<p>ツールの使い方は5ステップで、アカウント登録もアップロードも不要です。すべて自分の端末の中で行われます。</p>\n<ol>\n<li>調べたい画像をドラッグするか、選択します。JPG、PNG、WebP、HEIC、GIF、BMP、SVGに対応し、1ファイル最大20MBまで。Ctrl+Vでの貼り付けもできます。</li>\n<li>上部の概要とプライバシーリスク表示を確認します。形式、画素数、ファイルサイズと、注意が必要なタグが見つかったかどうかが分かります。</li>\n<li>GPS位置情報の警告を確認します。座標があれば、警告ボックスに正確な緯度と経度が表示されます。</li>\n<li>抽出されたメタデータの一覧を確認します。カメラ、EXIF、GPS、PNG・WebPチャンク、ファイル情報ごとにグループ分けされ、注意が必要な項目には琥珀色のPrivacy Tagラベルが付きます。</li>\n<li>JSONでコピー・エクスポートするか、メタデータを削除します。「Copy JSON」でレポート全体をコピー、「Export JSON」で.jsonファイルを保存、「Strip Metadata」でファイルをきれいにできます。</li>\n</ol>\n<p>このツールは読み取り専用です。ブラウザのメモリ上でヘッダーを読んで表示するだけで、元のファイルを変更したり、圧縮したり、削除したりすることはありません。</p>\n<p>更新せずに次々とファイルを調べることもできます。概要バーの赤いゴミ箱アイコンをクリックしてアップロード画面に戻し、次の画像をドラッグするだけです。</p>\n<h2 id=\"json-export\">JSONレポートのコピーと保存</h2>\n<p>メタデータを記録として残したり、誰かと共有したり、バグ報告に貼り付けたりしたい場面があります。ツールは解析結果全体を構造化されたJSON形式で出力できます。</p>\n<p>概要バーの「Copy JSON」をクリックすると、ImageMetadataReport全体がクリップボードにコピーされます。ドキュメントやチケット、チャットメッセージにそのまま貼り付けられます。</p>\n<p>「Export JSON」をクリックすると、画像のファイル名に「_metadata」を付けた.jsonファイルがダウンロードされます。開発者はこうしたレポートを、画像処理の不具合調査やファイル仕様の記録に使います。</p>\n<p>JSONには、ツールがデコードしたすべての項目が、画面の一覧と同じグループ分けで含まれます。2つのファイルを比較したり、削除前の状態を記録しておいたりするのに便利です。</p>\n<p>確認手順を実際に試したい方は、<a href=\"/ja/blog/gazou-metadeta-no-mikata/\">画像メタデータの見方</a>もご覧ください。各項目が何を意味するのかは、<a href=\"/ja/blog/exif-data-kaisetsu/\">EXIF情報とは？写真に隠れたデータを解説</a>で詳しく説明しています。</p>\n<h2 id=\"verifying-clean-files\">削除済みファイルの確認方法</h2>\n<p>メタデータ確認ツールの最も便利な使い方の一つが、ほかのツールの仕上がりをチェックすることです。写真のメタデータを削除したら、きれいになったファイルをもう一度ツールにドラッグして、本当にタグが消えたか確認しましょう。</p>\n<p>削除が成功していれば、緑色のバナーで「EXIF、GPS、隠れたカメラタグは検出されませんでした」と表示され、GPS警告も出ません。これは推測ではなく、ファイルのバイト列を実際に調べた結果です。</p>\n<p>この確認が重要なのは、削除をうたうツールの中には、一部のチャンクを残してしまうものがあるからです。PNGのtEXtブロックやJPEGのコメントが、いい加減なクリーナーでは残ることがあります。ツールはそうした残り物も見逃しません。</p>\n<p>大切な写真では「確認→削除→再確認」を習慣にしましょう。2回目の確認は数秒で終わり、1回目の作業が確実だったことを証明してくれます。</p>\n<p>削除後のファイルにまだタグが残っている場合は、<a href=\"/ja/gazou-metadeta-sakujo/\">画像メタデータ削除ツール</a>の「Full Canvas Re-encode」オプションを試してください。画素を一から再構築するため、受け継いだバイナリ部分がすべて消えます。</p>\n<h2 id=\"when-to-check-metadata\">チェックすべきタイミング</h2>\n<p>写真が自分の手元を離れるときは、いつでもメタデータを確認しましょう。リスクは写真そのものではなく、誰がダウンロードして何を読み取れるかにあります。</p>\n<ul>\n<li>フリマアプリに出品する前。購入者はフル解像度の画像をダウンロードできます。</li>\n<li>家族写真をSNSに投稿する前。特に自宅や学校で撮った写真は要注意です。</li>\n<li>写真を記者やクライアント、見知らぬ人に送る前。さらに転送される可能性があります。</li>\n<li>ブログやウェブサイトに写真を掲載する前。ファイルは何年もダウンロード可能な状態で残ります。</li>\n<li>写真を受け取った後。いつ・どこで・どのカメラで撮られたかが分かります。</li>\n<li>画像処理の不具合を調べるとき。各処理ステップでどの項目が残るかが分かります。</li>\n</ul>\n<p>写真家がメタデータを確認する理由は別にあります。素晴らしい一枚の露出設定は、再現したいレシピそのものです。ISO、絞り、シャッタースピードはツールですぐに読み取れます。</p>\n<p>開発者が確認するのは、画像の挙動がおかしいときです。向きフラグの誤り、想定外のDPI値、隠れたカラープロファイルなどが、表示バグの原因になっていることがよくあります。</p>\n<h2 id=\"viewer-limits\">ツールの限界</h2>\n<p>このツールは、限界についても正直です。JavaScriptで動作する本格的なバイナリ解析はJPEG、PNG、WebPを対象としており、この3形式で最も詳しいレポートが得られます。</p>\n<p>HEIC、GIF、BMP、SVGについては、ファイル形式、ファイルサイズ、画素数といった基本情報を確実に表示します。ただし、バイナリのEXIFチャンク全体の抽出はこれらの形式では行われないため、同じ写真でもJPEGより情報が少なくなる場合があります。</p>\n<p>貼り付けたスクリーンショットには、通常カメラタグがありません。OSのクリップボードは元のカメラファイルではなく生の画像データを渡すため、カメラヘッダーがそもそも存在しないのです。</p>\n<p>WhatsAppやInstagramからダウンロードした写真も、EXIFタグがゼロの場合がほとんどです。SNSやメッセージアプリは、サーバーへのアップロード時にEXIF・カメラ・GPSヘッダーを自動で削除するからです。</p>\n<p>1ファイル20MBまでの制限は、フル解像度のデジタル一眼レフのJPEGや、詳細なPNG書き出し、非圧縮のBMPファイルにも十分対応します。もっと大きなファイルは、まず<a href=\"/ja/\">画像圧縮ツール</a>で小さくしてから確認しましょう。</p>\n<h2 id=\"metadata-on-mobile\">スマホでの確認方法</h2>\n<p>写真のほとんどはスマホで撮られるため、ツールはモバイルブラウザでも使えます。モバイル版SafariやChromeでページを開き、カメラロールから写真を選ぶだけです。</p>\n<p>ネットに投稿する直前に、隠れたGPS座標やカメラ情報をスマホで確認できます。このタイミングこそ確認が最も重要です。投稿のほとんどはスマホから行われるからです。</p>\n<p>画面の構成はパソコンと同じです。概要バナー、GPS警告、グループ分けされた一覧が表示され、「Copy JSON」や「Strip Metadata」も同じように使えます。</p>\n<p>スマホの写真にGPS情報が見つかったら、共有する前に削除しましょう。<a href=\"/ja/gazou-metadeta-sakujo/\">画像メタデータ削除ツール</a>もモバイルで動作するので、確認から削除までの一連の作業がポケットの中で完結します。</p>\n<h2 id=\"metadata-viewer-summary\">まとめ</h2>\n<p>画像のメタデータとは、すべての写真に隠れているデータのことです。カメラの設定、撮影日時、ソフトの記録、そして場合によってはGPS座標まで含まれます。確認ツールを使えば、それらが見えるようになります。</p>\n<p>写真を公開する前、特に自宅や学校、職場で撮った写真は必ず確認しましょう。まずGPS警告を見て、次に琥珀色のPrivacy Tagラベルをチェックします。</p>\n<p>記録が必要なときはJSONで保存し、削除したファイルは再確認して本当にきれいになったか確かめます。ツールは無料で、登録不要。写真がアップロードされることは決してありません。</p>\n<p>まずは<a href=\"/ja/gazou-metadeta-kakunin/\">画像メタデータ確認ツール</a>で調べて、削除が必要なファイルはそのまま<a href=\"/ja/gazou-metadeta-sakujo/\">画像メタデータ削除ツール</a>へ。写真には、自分が共有すると決めたものだけを載せましょう。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"EXIF、XMP、IPTCのメタデータは何が違うのですか？","answer":"EXIFはカメラが書き込むデータで、露出設定や撮影日時、GPS座標などが含まれます。XMPはAdobeのXML形式のパケットで、編集履歴や評価、説明文などを記録できます。IPTCは報道・出版業界の標準で、キャプションやクレジット、キーワードを扱います。1枚の写真に3つすべてが入っていることもあり、ツールはEXIFやXMP形式の項目、PNGのテキストチャンクをまとめて一覧表示します。"},{"question":"メタデータ確認ツールで写真の撮影場所が分かりますか？","answer":"写真にGPS座標が含まれていれば分かります。ツールはGPSIFDタグを10進数の緯度・経度に変換し、警告バナーで表示します。GPSタグがなければ場所を推測することはできません。撮影日時やカメラ情報から場所を想像できる場合もありますが、証明にはなりません。"},{"question":"デジタル一眼レフやミラーレスで撮った写真にも対応していますか？","answer":"はい、対応しています。デジタル一眼レフやミラーレスカメラは、レンズの機種、焦点距離、絞り、シャッタースピード、ISO感度、測光モードなど、豊富なEXIFデータを書き込みます。ツールはExifIFDディレクトリからこれらをすべて読み取ります。最大20MBまでのフル解像度JPEGに対応しているので、ほとんどのカメラの書き出しファイルを扱えます。"},{"question":"写真によってメタデータがあったりなかったりするのはなぜですか？","answer":"カメラロールにあるオリジナルファイルには、メタデータが丸ごと残っています。一方、WhatsAppやInstagram、Facebook、メールを経由した写真は、アップロード時にEXIFやGPSヘッダーが削除されるため、ほとんど残っていません。スクリーンショットもカメラタグがありません。クリップボードが渡すのは生の画素データだけで、元のカメラファイルではないからです。"},{"question":"オンラインのメタデータ確認ツールでプライベートな写真を調べても安全ですか？","answer":"ツールによります。このツールはブラウザの中でファイルのバイト列を解析するため、1バイトも端末の外に出ません。サーバーへのアップロードは一切ありません。逆に、アップロードを要求するツールは避けましょう。削除されていない写真をサーバーに送ると、GPS情報やカメラの詳細を第三者に渡すことになります。"},{"question":"ほかの人から送られてきた写真も確認できますか？","answer":"はい、できます。写真を保存してツールにドラッグすれば、いつ撮影されたか、どのカメラで撮られたか、GPS座標があるかどうかが一覧で分かります。ただし、削除済みのファイルは何も表示されません。それはメタデータが削除された証拠であって、写真がオリジナルである証拠ではない点に注意してください。"}];
